        // Fund the contract with some initial balance for the call
        vm.deal(address(c), _value);
        // Send money from contract to _target
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.sendMoney.selector, _target, _value));
        // The reference C always succeeds because it sends its own balance
