pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address target, uint256 value) public {
        // Bound value to avoid excessive gas
        value = bound(value, 1, 100000 ether);

        // Record owner's balance before sendMoney
        address owner = c.owner();
        uint256 ownerBalanceBefore = owner.balance;
        uint256 contractBalanceBefore = address(c).balance;

        // Call sendMoney to send value to target
        (bool success, ) = address(c).call{value: value}(abi.encodeWithSignature("sendMoney(address,uint256)", target, value));

        // Only proceed if sendMoney succeeded (value <= contract balance or contract receives funds? But contract starts empty, so we need to fund it)
        // To make sendMoney always succeed, we need to fund the contract first
        // However, this is a fuzz test; we can fund the contract via fallback
        // Instead, we assume the contract has enough funds by sending ether before
        // Better: call sendMoney only after the contract has received ether
        // Since C's fallback accepts ether, we can send ether first
    }

    // A simpler approach: use a separate function that funds the contract first
    function testFuzz_property_2(address target, uint256 value) public {
        // Ensure contract has some balance by funding it via fallback
        value = bound(value, 1, 100000 ether);

        // Fund the contract
        address payable cAddress = payable(address(c));
        (bool fundSuccess, ) = cAddress.call{value: value}("");
        assertTrue(fundSuccess);

        // Record owner's balance
        address owner = c.owner();
        uint256 ownerBalanceBefore = owner.balance;

        // Record withdrawAll result before calling sendMoney
        c.withdrawAll();
        uint256 balanceAfterWithdraw = address(c).balance;

        // Now call sendMoney to send some value to target
        uint256 sendAmount = value / 2;
        vm.assume(sendAmount > 0 && sendAmount <= address(c).balance);
        c.sendMoney(target, sendAmount);

        // After sendMoney, call withdrawAll again and check that owner gets the full balance
        uint256 contractBalanceBeforeWithdraw = address(c).balance;
        c.withdrawAll();
        uint256 ownerBalanceAfter = owner.balance;
        uint256 contractBalanceAfter = address(c).balance;

        // The owner should have gained the contract's balance at the time of withdrawal
        assertTrue(ownerBalanceAfter - ownerBalanceBefore == contractBalanceBeforeWithdraw);
    }
    // Note: The above test may fail on the buggy version because withdrawAll(0) doesn't transfer the full balance
}

