            assertEq(address(c).balance, contractBalanceBefore, "Contract balance should remain unchanged on revert");
        } else {
            // If it didn't revert, then the target should have received the ether
            if (!reverted) {
                assertEq(address(_target).balance, targetBalanceBefore + _value, "Target should receive the ether on successful call");
            }
        }
    }
}

