        (bool success, ) = address(c).call(abi.encodeWithSignature("sendMoney(address,uint256)", target, value));

        // Rule: If the call succeeded, then the value was transferred and no revert
        // If the call reverted, no ether was transferred
        if (success) {
            assertTrue(address(c).balance == balanceBefore - value, "contract balance decreased by value");
            assertTrue(address(target).balance == targetBalanceBefore + value, "target balance increased by value");
        } else {
            // call reverted
            assertTrue(address(c).balance == balanceBefore, "balance unchanged on revert");
            assertTrue(address(target).balance == targetBalanceBefore, "target balance unchanged on revert");
        }
    }
}

